/**
 * Logical analysis workspaces and their physical output roots.
 *
 * A workspace id is generated by the platform and never derived from a path.
 * Switching the workspace selected by a request changes only where a new job
 * writes; it never changes the resource grants used to read host data.
 *
 * @module @deepseek-ai/dsh-platform-services/integration/workspaces
 */

import type { IntegrationActor, WorkspaceRecord } from './types.ts'
import type { IntegrationStore } from './store.ts'
import { ensureDirectory, newObjectId, resolveWithin } from './files.ts'
import { IntegrationError } from './errors.ts'

/** Longest accepted workspace display name. */
const MAX_WORKSPACE_NAME = 80

/** Owner-scoped workspace registry. */
export class WorkspaceService {
  private readonly store: IntegrationStore
  private readonly root: string
  private readonly now: () => number

  /**
   * @param store - metadata store.
   * @param root - workspace root from configuration.
   * @param now - clock injection.
   */
  constructor(store: IntegrationStore, root: string, now: () => number = Date.now) {
    this.store = store
    this.root = root
    this.now = now
  }

  /**
   * Create one workspace for the actor.
   * @param actor - validated session identity.
   * @param name - user-visible display name.
   * @returns the created workspace.
   */
  create(actor: IntegrationActor, name: string): WorkspaceRecord {
    const trimmed = name.trim()
    if (trimmed === '' || trimmed.length > MAX_WORKSPACE_NAME) {
      throw new IntegrationError('workspace-invalid', `workspace name must be 1-${String(MAX_WORKSPACE_NAME)} characters`)
    }
    const workspace: WorkspaceRecord = {
      id: newObjectId(),
      ownerUserId: actor.userId,
      name: trimmed,
      createdAt: new Date(this.now()).toISOString(),
    }
    ensureDirectory(this.root, actor.userId, workspace.id)
    this.store.insertWorkspace(workspace)
    return workspace
  }

  /**
   * List the actor's workspaces.
   * @param actor - validated session identity.
   * @returns workspaces in creation order.
   */
  list(actor: IntegrationActor): WorkspaceRecord[] {
    return this.store.listWorkspaces(actor.userId)
  }

  /**
   * Resolve one owner-scoped workspace.
   * @param actor - validated session identity.
   * @param workspaceId - requested workspace id.
   * @returns the workspace.
   * @throws {IntegrationError} when the workspace does not belong to the actor.
   */
  require(actor: IntegrationActor, workspaceId: string): WorkspaceRecord {
    const workspace = this.store.findWorkspace(workspaceId, actor.userId)
    if (workspace === undefined) {
      throw new IntegrationError('workspace-not-found', 'unknown workspace', 404)
    }
    return workspace
  }

  /**
   * Create (when absent) and return one job's output directory.
   * @param workspace - owner-verified workspace.
   * @param jobId - job id.
   * @returns the absolute output directory.
   */
  jobOutputDirectory(workspace: WorkspaceRecord, jobId: string): string {
    return ensureDirectory(this.root, workspace.ownerUserId, workspace.id, 'jobs', jobId)
  }

  /**
   * Resolve one artifact path inside a workspace job output directory.
   * @param workspace - owner-verified workspace.
   * @param jobId - job id.
   * @param relativePath - POSIX relative artifact path from metadata.
   * @returns the absolute file path.
   */
  artifactPath(workspace: WorkspaceRecord, jobId: string, relativePath: string): string {
    const segments = relativePath.split('/')
    if (segments.length === 0 || segments.some(segment => segment === '' || segment === '.' || segment === '..')) {
      throw new IntegrationError('artifact-not-found', 'artifact path is invalid', 404)
    }
    return resolveWithin(this.root, workspace.ownerUserId, workspace.id, 'jobs', jobId, ...segments)
  }
}
